    const body = { confirmed: true, scope, accountId: scope === 'account' ? accountId : '', items: selected.map(item => ({ ...(item.candidateId ? { candidateId: item.candidateId } : {}), title: item.title.trim(), text: item.text.trim() })) }, fingerprint = JSON.stringify(body);
