  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  const deliveryValid = () => alive.current && session.current === workSession();
  function recordDelivery(id: string, delivered: boolean, error = '系统未确认显示提醒，站内通知仍保留。') { if (!deliveryValid()) return; setDeliveryFailures(current => { const next = { ...current }; if (delivered) delete next[id]; else next[id] = error; return next; }); }
  function retryDesktop(id: string) {
    if (!window.studioDesktop?.notifyWork || !deliveryValid() || sending.current.has(id)) return;
    shown.current.add(id);
    void deliveryAction.execute(async isCurrent => { sending.current.add(id); try { return await deliverWorkNotification({ notificationId: id, sessionToken: session.current, sound }, () => deliveryValid() && isCurrent()); } finally { sending.current.delete(id); } }, async result => { recordDelivery(id, result.delivered); await inbox.reload(); });
  }
  const navigateNotification = useRef<(id: string) => void>(() => {});
  navigateNotification.current = id => { void action.execute(() => api<{ notification: WorkNotification }>(`/notifications/${uri(id)}`), async (result, isCurrent) => { const item = result.notification, destination = item.target || item; if (!destination.taskId) return; await api(`/notifications/${uri(id)}/read`, 'POST'); if (!isCurrent()) return; setOpen(false); go('controller', destination.projectId || item.projectId, { taskId: destination.taskId, runId: destination.runId, artifactId: destination.artifactId, artifactVersion: destination.artifactVersion ? String(destination.artifactVersion) : undefined }); await inbox.reload(); }); };
  useEffect(() => { const show = () => { if (document.visibilityState === 'visible') { setReturned(true); void inbox.reload(); } }; document.addEventListener('visibilitychange', show); return () => document.removeEventListener('visibilitychange', show); }, [inbox.reload]);
  useEffect(() => window.studioDesktop?.onWorkNotification?.(value => navigateNotification.current(value.notificationId)), []);
  useEffect(() => { if (!desktop || !window.studioDesktop?.notifyWork || !deliveryValid()) return; const pending = (inbox.value?.items || []).filter(item => !item.readAt && !item.deliveredAt && !item.deliveryAttemptedAt && !shown.current.has(item.id)); for (const item of pending) { shown.current.add(item.id); sending.current.add(item.id); void deliverWorkNotification({ notificationId: item.id, sessionToken: session.current, sound }, deliveryValid).then(result => recordDelivery(item.id, result.delivered)).catch(error => recordDelivery(item.id, false, workError(error))).finally(() => sending.current.delete(item.id)); } }, [desktop, sound, inbox.value]);
  useEffect(() => { if (!open) return; const close = (event: PointerEvent) => { if (event.target instanceof Node && !root.current?.contains(event.target)) setOpen(false); }; const keys = (event: KeyboardEvent) => { if (event.key === 'Escape') { setOpen(false); root.current?.querySelector<HTMLButtonElement>('button')?.focus(); } }; document.addEventListener('pointerdown', close); document.addEventListener('keydown', keys); return () => { document.removeEventListener('pointerdown', close); document.removeEventListener('keydown', keys); }; }, [open]);
  if (LOCAL_DATA) return null;
