type PlanningQuote = { quoteId: string; estimateUSD: number; model: string; label: string; expiresAt: string; scope: 'planning-only' };
export function PlanningAction({ goal, accountIds, taskId, projectId, disabled = false, onPlan, model: controlledModel, onModelChange, initialRunId }: { goal: string; accountIds: string[]; taskId?: string; projectId?: string; disabled?: boolean; onPlan?: (plan: WorkPlan) => void | Promise<void>; model?: string; onModelChange?: (model: string) => void; initialRunId?: string }) {
  const { project, settings, go, target } = useStudio(), destination = projectId || project?.id || '';
  const [localModel, setLocalModel] = useState(settings.routes.strategy), [quote, setQuote] = useState<PlanningQuote | null>(null), [budget, setBudget] = useState(0), [consent, setConsent] = useState(false), [runId, setRunId] = useState(initialRunId || '');
  const model = controlledModel ?? localModel, setModel = (value: string) => { if (disabled) return; if (onModelChange) onModelChange(value); else setLocalModel(value); };
  const action = useWorkAction(), request = useRef(workId()), fingerprint = JSON.stringify([destination, goal.trim(), accountIds, model, taskId]), latestInput = useRef(fingerprint); latestInput.current = fingerprint;
  const result = useWorkResource<{ run: WorkRun; plan?: WorkPlan; question?: string }>(runId ? `/planning-runs/${uri(runId)}` : null, 2000);
  useEffect(() => { setQuote(null); setConsent(false); request.current = workId(); }, [fingerprint]);
  const deliveredPlan = useRef('');
  useEffect(() => { if (initialRunId) { setRunId(initialRunId); deliveredPlan.current = ''; } }, [initialRunId]);
  useEffect(() => {
    const next = result.value?.plan;
    if (!next || !onPlan || deliveredPlan.current === `${next.id}:${next.version}` || !target.taskId || target.runId !== runId) return;
    deliveredPlan.current = `${next.id}:${next.version}`;
    void onPlan(next);
  }, [result.value?.plan, onPlan, target.taskId, target.runId, runId]);

  const running = !!runId && (!result.value || activeWork(result.value.run.status)), expired = quote && Number.isFinite(Date.parse(quote.expiresAt)) && Date.parse(quote.expiresAt) <= Date.now();
  async function estimate() { const captured = fingerprint; await action.execute(() => api<PlanningQuote>(`/projects/${uri(destination)}/planning/estimate`, 'POST', { goal: goal.trim(), accountIds, model, ...(taskId ? { taskId } : {}) }), next => { if (captured !== latestInput.current) return; setQuote(next); setBudget(Math.ceil(next.estimateUSD * 100) / 100); setConsent(false); request.current = workId(); }); }
  return <section className="work-planning-action"><Field label="规划模型"><select value={model} disabled={action.pending || running} onChange={event => setModel(event.target.value)}>{Object.entries(settings.models).map(([id, item]) => <option key={id} value={id}>{item.label}</option>)}</select></Field><button type="button" className="button" disabled={disabled || action.pending || running || !goal.trim() || !destination} onClick={() => void estimate()}><Sparkles size={15}/>{taskId ? '让总控整理修改方案 · 先估算' : '估算 AI 规划费用（不调用模型）'}</button>{quote && !running && <div className="work-approval"><p>{quote.label || quote.model} · 规划估算 {money(quote.estimateUSD)}。本次仅生成计划建议，不授权任何业务任务执行。</p><Field label="单独批准的规划费用额度（美元）"><input type="number" min={quote.estimateUSD} max={100} step={0.01} value={budget} onChange={event => { setBudget(Number(event.target.value)); setConsent(false); }}/></Field><label className="checkbox-row"><input type="checkbox" checked={consent} onChange={event => setConsent(event.target.checked)}/><span>同意此次 AI 规划调用及费用。计划生成后，仍需另外核对并批准业务执行。</span></label>{expired && <p className="work-error">此估算已过期，请重新估算。</p>}<button type="button" className="button primary" disabled={!consent || action.pending || !!expired || budget < quote.estimateUSD || !Number.isFinite(budget)} onClick={() => void action.execute(() => api<{ run: WorkRun }>(`/projects/${uri(destination)}/planning-runs`, 'POST', { quoteId: quote.quoteId, planningBudgetUSD: budget, idempotencyKey: request.current }), next => { setRunId(next.run.id); setQuote(null); setConsent(false); go('controller', destination, { taskId: next.run.taskId, runId: next.run.id }); })}>确认规划费用并生成建议</button></div>}{runId && <div className="work-planning-progress"><p><WorkStatusBadge status={result.value?.run.status || 'queued'}/>总控 AI 规划 · 仅显示后台真实状态</p>{result.value?.run.error && <ErrorNote error={result.value.run.error}/>}<button type="button" className="text-button" disabled={!result.value?.run.taskId} onClick={() => { const run = result.value?.run; if (run) go('controller', run.projectId, { taskId: run.taskId, runId: run.id }); }}>查看规划活动与回执 <ArrowRight size={14}/></button>{result.value?.question && <p className="info-box">需要补充：{result.value.question}</p>}{result.value?.plan && <div className="work-soft-note"><p>计划建议已保存，尚未授权业务执行。</p><button type="button" className="button primary" onClick={() => { const plan = result.value!.plan!; if (onPlan) void onPlan(plan); else go('controller', plan.projectId, { planId: plan.id }); }}>核对计划草案 <ArrowRight size={14}/></button></div>}</div>}<ErrorNote error={action.error || result.error}/></section>;
}
